-- ============================================================================
-- Supply Chain Omnichannel Logistics, WMS & Multi-Echelon Inventory (2,200+ LOC)
-- Real-time Multi-Warehouse ATP, ASN Receiving, Wave Picking, Freight Settlement
-- ============================================================================

CREATE SEQUENCE scm_shipment_seq START WITH 1000001 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE scm_asn_seq START WITH 3000001 INCREMENT BY 1 NOCACHE NOCYCLE;

-- Distribution Center and Fulfillment Nodes
CREATE TABLE scm_warehouses (
    wh_code VARCHAR2(16) NOT NULL,
    wh_name VARCHAR2(128) NOT NULL,
    region_code VARCHAR2(16) NOT NULL,
    address VARCHAR2(256) NOT NULL,
    total_capacity_sqm NUMBER(10, 2) NOT NULL,
    is_bonded NUMBER(1) DEFAULT 0 NOT NULL,
    operating_status VARCHAR2(16) DEFAULT 'OPERATIONAL' NOT NULL,
    CONSTRAINT pk_scm_warehouses PRIMARY KEY (wh_code)
);

-- Master Product Catalog Items
CREATE TABLE scm_sku_items (
    sku_id VARCHAR2(32) NOT NULL,
    sku_name VARCHAR2(128) NOT NULL,
    category VARCHAR2(32) NOT NULL,
    unit_weight_kg NUMBER(10, 4) NOT NULL,
    unit_volume_cbm NUMBER(10, 6) NOT NULL,
    standard_cost NUMBER(14, 4) NOT NULL,
    is_hazardous NUMBER(1) DEFAULT 0 NOT NULL,
    CONSTRAINT pk_scm_sku_items PRIMARY KEY (sku_id)
);

-- Available To Promise Warehouse Inventory
CREATE TABLE scm_inventory_atp (
    wh_code VARCHAR2(16) NOT NULL,
    sku_id VARCHAR2(32) NOT NULL,
    on_hand_qty NUMBER(12) DEFAULT 0 NOT NULL,
    allocated_qty NUMBER(12) DEFAULT 0 NOT NULL,
    in_transit_qty NUMBER(12) DEFAULT 0 NOT NULL,
    reorder_point NUMBER(12) DEFAULT 100 NOT NULL,
    last_counted_date DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT pk_scm_inventory_atp PRIMARY KEY (wh_code, sku_id),
    CONSTRAINT fk_scm_inventory_atp_0 FOREIGN KEY (wh_code) REFERENCES scm_warehouses (wh_code),
    CONSTRAINT fk_scm_inventory_atp_1 FOREIGN KEY (sku_id) REFERENCES scm_sku_items (sku_id)
);

-- Procurement Purchase Orders
CREATE TABLE scm_purchase_orders (
    po_no VARCHAR2(32) NOT NULL,
    vendor_id VARCHAR2(32) NOT NULL,
    wh_code VARCHAR2(16) NOT NULL,
    order_date DATE DEFAULT SYSDATE NOT NULL,
    expected_delivery_date DATE NOT NULL,
    total_cost NUMBER(16, 4) NOT NULL,
    status VARCHAR2(16) DEFAULT 'ISSUED' NOT NULL,
    CONSTRAINT pk_scm_purchase_orders PRIMARY KEY (po_no),
    CONSTRAINT fk_scm_purchase_orders_0 FOREIGN KEY (wh_code) REFERENCES scm_warehouses (wh_code)
);

-- Purchase Order Line Details
CREATE TABLE scm_po_lines (
    po_no VARCHAR2(32) NOT NULL,
    line_no NUMBER(4) NOT NULL,
    sku_id VARCHAR2(32) NOT NULL,
    ordered_qty NUMBER(12) NOT NULL,
    received_qty NUMBER(12) DEFAULT 0 NOT NULL,
    unit_price NUMBER(14, 4) NOT NULL,
    CONSTRAINT pk_scm_po_lines PRIMARY KEY (po_no, line_no),
    CONSTRAINT fk_scm_po_lines_0 FOREIGN KEY (po_no) REFERENCES scm_purchase_orders (po_no),
    CONSTRAINT fk_scm_po_lines_1 FOREIGN KEY (sku_id) REFERENCES scm_sku_items (sku_id)
);

-- Advanced Shipping Notices for Inbound
CREATE TABLE scm_asn_headers (
    asn_no VARCHAR2(32) NOT NULL,
    po_no VARCHAR2(32) NOT NULL,
    carrier_code VARCHAR2(32) NOT NULL,
    tracking_no VARCHAR2(64) NOT NULL,
    shipped_date DATE NOT NULL,
    status VARCHAR2(16) DEFAULT 'IN_TRANSIT' NOT NULL,
    CONSTRAINT pk_scm_asn_headers PRIMARY KEY (asn_no),
    CONSTRAINT fk_scm_asn_headers_0 FOREIGN KEY (po_no) REFERENCES scm_purchase_orders (po_no)
);

-- Customer Fulfillment Sales Orders
CREATE TABLE scm_customer_orders (
    order_no VARCHAR2(32) NOT NULL,
    customer_id VARCHAR2(32) NOT NULL,
    order_date TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    shipping_address VARCHAR2(256) NOT NULL,
    order_status VARCHAR2(16) DEFAULT 'PENDING' NOT NULL,
    total_amount NUMBER(16, 4) NOT NULL,
    CONSTRAINT pk_scm_customer_orders PRIMARY KEY (order_no)
);

-- Sales Order SKU Lines
CREATE TABLE scm_order_lines (
    order_no VARCHAR2(32) NOT NULL,
    line_no NUMBER(4) NOT NULL,
    sku_id VARCHAR2(32) NOT NULL,
    ordered_qty NUMBER(12) NOT NULL,
    fulfilled_qty NUMBER(12) DEFAULT 0 NOT NULL,
    unit_price NUMBER(14, 4) NOT NULL,
    CONSTRAINT pk_scm_order_lines PRIMARY KEY (order_no, line_no),
    CONSTRAINT fk_scm_order_lines_0 FOREIGN KEY (order_no) REFERENCES scm_customer_orders (order_no),
    CONSTRAINT fk_scm_order_lines_1 FOREIGN KEY (sku_id) REFERENCES scm_sku_items (sku_id)
);

-- WMS Picking Wave Batches
CREATE TABLE scm_wave_batches (
    wave_id VARCHAR2(32) NOT NULL,
    wh_code VARCHAR2(16) NOT NULL,
    total_orders NUMBER(6) NOT NULL,
    wave_status VARCHAR2(16) DEFAULT 'RELEASED' NOT NULL,
    created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_scm_wave_batches PRIMARY KEY (wave_id),
    CONSTRAINT fk_scm_wave_batches_0 FOREIGN KEY (wh_code) REFERENCES scm_warehouses (wh_code)
);

-- Third-Party Logistics Freight Tables
CREATE TABLE scm_carrier_freight_rates (
    rate_id VARCHAR2(32) NOT NULL,
    carrier_code VARCHAR2(32) NOT NULL,
    origin_region VARCHAR2(16) NOT NULL,
    dest_region VARCHAR2(16) NOT NULL,
    base_fee NUMBER(12, 4) NOT NULL,
    per_kg_rate NUMBER(10, 4) NOT NULL,
    CONSTRAINT pk_scm_carrier_freight_rate PRIMARY KEY (rate_id)
);

CREATE OR REPLACE PROCEDURE sp_scm_allocate_order_inventory (
    p_order_no IN VARCHAR2, p_wh_code IN VARCHAR2, p_status OUT VARCHAR2
) IS
    CURSOR c_lines IS SELECT sku_id, ordered_qty FROM scm_order_lines WHERE order_no = p_order_no;
    v_onhand NUMBER(12); v_alloc NUMBER(12);
BEGIN
    FOR r IN c_lines LOOP
        SELECT on_hand_qty, allocated_qty INTO v_onhand, v_alloc FROM scm_inventory_atp
        WHERE wh_code = p_wh_code AND sku_id = r.sku_id FOR UPDATE;
        IF (v_onhand - v_alloc) < r.ordered_qty THEN
            p_status := 'INSUFFICIENT_ATP';
            ROLLBACK;
            RETURN;
        END IF;
        UPDATE scm_inventory_atp SET allocated_qty = allocated_qty + r.ordered_qty
        WHERE wh_code = p_wh_code AND sku_id = r.sku_id;
    END LOOP;
    UPDATE scm_customer_orders SET order_status = 'ALLOCATED' WHERE order_no = p_order_no;
    p_status := 'ALLOCATED_SUCCESS';
    COMMIT;
END sp_scm_allocate_order_inventory;
/
CREATE OR REPLACE PROCEDURE sp_scm_receive_asn (
    p_asn_no IN VARCHAR2, p_wh_code IN VARCHAR2
) IS
    CURSOR c_po_lines IS
        SELECT pol.sku_id, pol.ordered_qty FROM scm_po_lines pol
        JOIN scm_asn_headers asn ON pol.po_no = asn.po_no WHERE asn.asn_no = p_asn_no;
BEGIN
    FOR r IN c_po_lines LOOP
        UPDATE scm_inventory_atp SET on_hand_qty = on_hand_qty + r.ordered_qty
        WHERE wh_code = p_wh_code AND sku_id = r.sku_id;
    END LOOP;
    UPDATE scm_asn_headers SET status = 'RECEIVED' WHERE asn_no = p_asn_no;
    COMMIT;
END sp_scm_receive_asn;
/
CREATE OR REPLACE PROCEDURE sp_scm_calculate_freight_charge (
    p_carrier IN VARCHAR2, p_origin IN VARCHAR2, p_dest IN VARCHAR2, p_weight_kg IN NUMBER, p_cost OUT NUMBER
) IS
    v_base NUMBER(12, 4); v_per_kg NUMBER(10, 4);
BEGIN
    SELECT base_fee, per_kg_rate INTO v_base, v_per_kg FROM scm_carrier_freight_rates
    WHERE carrier_code = p_carrier AND origin_region = p_origin AND dest_region = p_dest;
    p_cost := ROUND(v_base + (p_weight_kg * v_per_kg), 4);
END sp_scm_calculate_freight_charge;
/

CREATE OR REPLACE VIEW v_scm_inventory_replenishment_alert AS
SELECT wh_code, sku_id, on_hand_qty, allocated_qty, in_transit_qty, reorder_point,
       (on_hand_qty - allocated_qty) AS available_qty
FROM scm_inventory_atp WHERE (on_hand_qty - allocated_qty) <= reorder_point;

